int[] sorted = {2, 5, 8, 12, 16, 23, 38, 56};
int target = 23;
int low = 0, high = sorted.length - 1;
int result = -1;
while (low <= high) {
    int mid = (low + high) / 2;
    if (sorted[mid] == target) {
        result = mid;
        break;
    } else if (sorted[mid] < target) {
        low = mid + 1;
    } else {
        high = mid - 1;
    }
}
System.out.println("Indeks: " + result);

